function iaAuthErrorMessage(a){const e=a&&a.message||"";return e.includes("Invalid login credentials")?"E-mail ou senha incorretos.":e.includes("User already registered")?"Já existe uma conta com esse e-mail.":e.includes("Password should be")?"A senha precisa ter pelo menos 6 caracteres.":e||"Não foi possível completar a ação agora."}async function iaSignUp(a,e){const{data:r,error:s}=await supabaseClient.auth.signUp({email:a.trim(),password:e});if(s)return{ok:!1,error:iaAuthErrorMessage(s)};if(!r.session)return{ok:!0,pendingEmailConfirmation:!0};const{error:i}=await supabaseClient.from("ia_profiles").insert({email:a.trim()});return i?{ok:!1,error:"Conta criada, mas houve um erro ao registrar seu perfil: "+i.message}:{ok:!0,pendingEmailConfirmation:!1}}async function iaLogin(a,e){const{data:r,error:s}=await supabaseClient.auth.signInWithPassword({email:a.trim(),password:e});return s?{ok:!1,error:iaAuthErrorMessage(s)}:{ok:!0,session:r.session}}async function iaIsLoggedIn(){const{data:a}=await supabaseClient.auth.getSession();return!!a.session}async function iaCurrentUser(){const{data:a}=await supabaseClient.auth.getUser();return a.user||null}async function iaLogout(){await supabaseClient.auth.signOut()}async function iaRequireAuth(){return!!await iaIsLoggedIn()||(window.location.href="login.html",!1)}async function iaGetOwnProfile(){const a=await iaCurrentUser();if(!a)return null;const{data:e,error:r}=await supabaseClient.from("ia_profiles").select("*").eq("user_id",a.id).maybeSingle();if(r)throw new Error(r.message);return e}async function iaIsAdmin(){const a=await iaCurrentUser();if(!a)return!1;const{data:e}=await supabaseClient.from("ia_admins").select("user_id").eq("user_id",a.id).maybeSingle();return!!e}